CREATE DATABASE IF NOT EXISTS ruraldoc CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ruraldoc;

CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medical_records (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, record_type VARCHAR(40) NOT NULL, title VARCHAR(255) NOT NULL, details TEXT NULL, file_url VARCHAR(500) NULL, recorded_date DATE NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_records_user (user_id, created_at), CONSTRAINT fk_records_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medicine_reminders (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, medicine_name VARCHAR(255) NOT NULL, dosage VARCHAR(120) NULL, frequency VARCHAR(120) NULL, reminder_time TIME NULL, times_per_day TINYINT UNSIGNED NOT NULL DEFAULT 1, start_date DATE NULL, end_date DATE NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_reminders_user (user_id, created_at), CONSTRAINT fk_reminders_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reminder_logs (id CHAR(36) PRIMARY KEY, reminder_id CHAR(36) NOT NULL, scheduled_time DATETIME NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', logged_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_logs_reminder (reminder_id, logged_at), CONSTRAINT fk_logs_reminder FOREIGN KEY (reminder_id) REFERENCES medicine_reminders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS symptom_check_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, input_text TEXT NULL, source_language VARCHAR(10) NULL, ai_response JSON NULL, urgency_level VARCHAR(20) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sessions_user (user_id, created_at), CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_messages (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, conversation_id CHAR(36) NOT NULL, role ENUM('user','assistant') NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_chat_conv (conversation_id, created_at), INDEX idx_chat_user (user_id), CONSTRAINT fk_chat_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id CHAR(36) NULL, feature VARCHAR(30) NOT NULL, model_name VARCHAR(80) NULL, urgency_level VARCHAR(20) NULL, language VARCHAR(10) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_time (created_at)) ENGINE=InnoDB;
